mapper.select:
SELECT o.id AS order_id, ticket.id AS ticket_id, ticket.status AS ticket_status, venue_section.name AS section_name, seat.row_label, seat.seat_label FROM orders o JOIN reservation_items item ON item.reservation_id = o.reservation_id JOIN event_seats event_seat ON event_seat.id = item.event_seat_id JOIN seats seat ON seat.id = event_seat.seat_id JOIN venue_sections venue_section ON venue_section.id = seat.section_id LEFT JOIN tickets ticket ON ticket.order_id = o.id AND ticket.event_seat_id = item.event_seat_id WHERE o.user_id = #{userId} AND o.id IN
#{orderId}
ORDER BY o.id, venue_section.display_order, seat.row_label, seat.seat_number, seat.id
